create table if not exists public.job_groups (id uuid primary key default gen_random_uuid(), ghl_project_display_id text, label text, created_at timestamptz not null default now(), created_by uuid);
create unique index if not exists job_groups_display_uq on public.job_groups(ghl_project_display_id) where ghl_project_display_id is not null;
alter table public.job_groups enable row level security;
create policy job_groups_read on public.job_groups for select using (auth.uid() is not null);
alter table public.jobs add column if not exists group_id uuid references public.job_groups(id) on delete set null;
create index if not exists idx_jobs_group on public.jobs(group_id) where group_id is not null;
comment on table public.job_groups is 'Links jobs that belong to one customer project — phases, add-ons and re-sells that share a GHL project # (or were linked by hand). Each job keeps its own contract, payments and stage; the group ties them together.';
create or replace function public.norm_display_id(p text) returns text language sql immutable as $fn$ select nullif(regexp_replace(coalesce(p,''), '\D', '', 'g'), '') $fn$;
create or replace function public.jobs_auto_group() returns trigger language plpgsql security definer set search_path to 'public' as $fn$ declare v_pid text := public.norm_display_id(new.ghl_project_display_id); v_gid uuid; begin if v_pid is null or length(v_pid) < 6 then return null; end if; if not exists (select 1 from public.jobs j where j.id <> new.id and public.norm_display_id(j.ghl_project_display_id) = v_pid) then return null; end if; select id into v_gid from public.job_groups where ghl_project_display_id = v_pid; if v_gid is null then select j.group_id into v_gid from public.jobs j where public.norm_display_id(j.ghl_project_display_id) = v_pid and j.group_id is not null order by j.number limit 1; end if; if v_gid is null then insert into public.job_groups(ghl_project_display_id, label) values (v_pid, 'GHL project ' || v_pid) returning id into v_gid; else update public.job_groups set ghl_project_display_id = coalesce(ghl_project_display_id, v_pid) where id = v_gid and not exists (select 1 from public.job_groups g2 where g2.ghl_project_display_id = v_pid and g2.id <> v_gid); end if; update public.jobs j set group_id = v_gid where public.norm_display_id(j.ghl_project_display_id) = v_pid and j.group_id is distinct from v_gid; return null; end $fn$;
create trigger jobs_auto_group after insert or update of ghl_project_display_id on public.jobs for each row execute function public.jobs_auto_group();
create or replace function public.link_jobs(p_job uuid, p_other uuid) returns uuid language plpgsql security definer set search_path to 'public' as $fn$ declare g1 uuid; g2 uuid; v_gid uuid; begin if not public.is_admin() then raise exception 'only the office can link jobs' using errcode = '42501'; end if; if p_job = p_other then raise exception 'a job cannot be linked to itself' using errcode = '22023'; end if; select group_id into g1 from public.jobs where id = p_job; select group_id into g2 from public.jobs where id = p_other; if not found then raise exception 'job not found' using errcode = 'P0002'; end if; v_gid := coalesce(g1, g2); if v_gid is null then insert into public.job_groups(label, created_by) values ('Linked by hand', auth.uid()) returning id into v_gid; end if; if g1 is not null and g2 is not null and g1 <> g2 then update public.jobs set group_id = g1 where group_id = g2; update public.job_groups set ghl_project_display_id = coalesce(public.job_groups.ghl_project_display_id, (select ghl_project_display_id from public.job_groups where id = g2)) where id = g1 and (select ghl_project_display_id from public.job_groups where id = g2) is not null and public.job_groups.ghl_project_display_id is null and false; end if; update public.jobs set group_id = v_gid where id in (p_job, p_other); return v_gid; end $fn$;
create or replace function public.unlink_job(p_job uuid) returns void language plpgsql security definer set search_path to 'public' as $fn$ declare v_gid uuid; begin if not public.is_admin() then raise exception 'only the office can unlink jobs' using errcode = '42501'; end if; select group_id into v_gid from public.jobs where id = p_job; update public.jobs set group_id = null where id = p_job; if v_gid is not null and (select count(*) from public.jobs where group_id = v_gid) = 1 then update public.jobs set group_id = null where group_id = v_gid; end if; end $fn$;
revoke execute on function public.link_jobs(uuid,uuid), public.unlink_job(uuid) from public, anon;
grant execute on function public.link_jobs(uuid,uuid), public.unlink_job(uuid) to authenticated;;
